func TestOpenAICompatibleGenerator_Generate(t *testing.T) {
	t.Parallel()

	client := &http.Client{
		Transport: roundTripFunc(func(r *http.Request) (*http.Response, error) {
			if r.Method != http.MethodPost {
				t.Fatalf("method = %s", r.Method)
			}
			if got := r.Header.Get("Authorization"); got != "Bearer test-key" {
				t.Fatalf("Authorization = %q", got)
			}

			var body map[string]any
			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
				t.Fatalf("decode request: %v", err)
			}
			if body["model"] != "gpt-test" {
				t.Fatalf("model = %v", body["model"])
			}

			return &http.Response{
				StatusCode: http.StatusOK,
				Header:     make(http.Header),
				Body: io.NopCloser(strings.NewReader(
					`{"choices":[{"message":{"content":"{\"intent\":\"Intent\",\"outcome\":\"Outcome\",\"learnings\":{\"repo\":[],\"code\":[],\"workflow\":[]},\"friction\":[],\"open_items\":[]}"}}]}`,
				)),
			}, nil
		}),
	}

	gen := &OpenAICompatibleGenerator{
		BaseURL:    "https://example.com/v1",
		Model:      "gpt-test",
		APIKey:     "test-key",
		HTTPClient: client,
	}

	summary, err := gen.Generate(context.Background(), Input{
		Transcript: []Entry{{Type: EntryTypeUser, Content: "Summarize this"}},
	})
	if err != nil {
		t.Fatalf("Generate() error = %v", err)
	}
	if summary.Intent != "Intent" {
		t.Fatalf("Intent = %q", summary.Intent)
	}
}

func TestOpenAICompatibleGenerator_MissingAPIKey(t *testing.T) {
	t.Parallel()

	gen := &OpenAICompatibleGenerator{}
	_, err := gen.Generate(context.Background(), Input{
		Transcript: []Entry{{Type: EntryTypeUser, Content: "Summarize this"}},
	})
	if err == nil {
		t.Fatal("expected error")
	}
}

type roundTripFunc func(*http.Request) (*http.Response, error)

func (fn roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) {
	return fn(r)
}

